'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {Download,Printer,RefreshCw} from 'lucide-react';
import {hotelRpc,type Membership} from '@/lib/pilot';
import {readPerformance,readWalkInStatistics,readGuestMixStatistics,type PerformanceReport} from '@/lib/historical-performance';
import {downloadReport,type ReportCell} from '@/lib/report-export';
import {frontOfficeStatisticsAvailability,frontOfficeStatisticsMetrics,frontOfficeStatisticsPeriods,frontOfficeStatisticsPeriodStatus,frontOfficeStatisticsValue,statisticsSections,type StatisticsMetric,type StatisticsPeriod} from '@/lib/front-office-statistics';

const columns:StatisticsPeriod['key'][]=['today','mtd','ytd','last_day','last_mtd','last_ytd'];
function display(value:string|null,format:StatisticsMetric['format']){if(value===null)return 'Unavailable';if(format==='money'){const negative=value.startsWith('-'),[whole,cents='00']=value.replace(/^-/,'').split('.');return `${negative?'-':''}$${whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${cents}`}if(format==='percent')return `${value}%`;return Number(value).toLocaleString('en-US')}
function periodLabel(period:StatisticsPeriod){return period.key==='today'?period.label:period.key==='last_day'?period.label:period.label}

export function FrontOfficeStatistics({membership,businessDate}:{membership:Membership;businessDate:string}){
 const [reportDate,setReportDate]=useState(businessDate),[reports,setReports]=useState<Partial<Record<StatisticsPeriod['key'],PerformanceReport>>>({}),[loadedKey,setLoadedKey]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const sequence=useRef(0),currentKey=membership.tenant_id+'/'+membership.property_id+'/'+reportDate;
 const periods=frontOfficeStatisticsPeriods(reportDate);
 const fresh=loadedKey===currentKey&&!busy&&!error&&columns.every(key=>reports[key]);
 const load=useCallback(async(date:string)=>{
  const seq=++sequence.current;setBusy(true);setError('');setLoadedKey('');setReports({});
  try{
   const ranges=frontOfficeStatisticsPeriods(date);
   const values=await Promise.all(ranges.map(async period=>{
    const scope={tenant:membership.tenant_id,property:membership.property_id,start:period.start,end:period.end};
    const [raw,walkInRaw,guestMixRaw]=await Promise.all([hotelRpc<unknown>('historical_performance_report',{p_tenant:membership.tenant_id,p_property:membership.property_id,p_start:period.start,p_end:period.end}),hotelRpc<unknown>('front_office_walk_in_statistics',{p_tenant:membership.tenant_id,p_property:membership.property_id,p_start:period.start,p_end:period.end}),hotelRpc<unknown>('front_office_guest_mix_statistics',{p_tenant:membership.tenant_id,p_property:membership.property_id,p_start:period.start,p_end:period.end})]);
    const report=readPerformance(raw,scope),walkIns=readWalkInStatistics(walkInRaw,scope),guestMix=readGuestMixStatistics(guestMixRaw,scope);
    return [period.key,{...report,days:report.days.map((day,index)=>({...day,walk_in_count:walkIns.days[index].walk_in_count,one_guest_room_count:guestMix.days[index].one_guest_room_count,two_guest_room_count:guestMix.days[index].two_guest_room_count,over_two_guest_room_count:guestMix.days[index].over_two_guest_room_count}))}] as const;
   }));
   if(seq===sequence.current){setReports(Object.fromEntries(values));setLoadedKey(membership.tenant_id+'/'+membership.property_id+'/'+date)}
  }catch(e){if(seq===sequence.current)setError(e instanceof Error?e.message:'Unable to load front-office statistics.')}finally{if(seq===sequence.current)setBusy(false)}
 },[membership.tenant_id,membership.property_id]);
 useEffect(()=>{const requestSequence=sequence;const timer=window.setTimeout(()=>void load(businessDate),0);return()=>{window.clearTimeout(timer);requestSequence.current++}},[businessDate,load]);
 const dateByKey=Object.fromEntries(periods.map(period=>[period.key,period])) as Record<StatisticsPeriod['key'],StatisticsPeriod>;
 function value(metric:StatisticsMetric,key:StatisticsPeriod['key']){const report=reports[key],period=dateByKey[key];return report?frontOfficeStatisticsStatisticsValue(metric.key,report,period):null}
 function coverage(key:StatisticsPeriod['key']){const report=reports[key],period=dateByKey[key];if(!report)return 'Not loaded';const status=frontOfficeStatisticsPeriodStatus(report,period);return `Closed ${status.closedDays}/${status.totalDays} · inventory ${status.inventoryDays}/${status.totalDays}`}
  function exportCsv(){if(!fresh)return;const metadata:ReportCell[][]=[['iRatePilot PMS','Front-office statistics'],['Property',membership.property_name],['Business date',reportDate],['Property time zone',membership.time_zone],['Data basis','Verified service-day closes. Out-of-inventory rooms equal physical units above configured capacity; available rooms exclude those units before maintenance/out-of-order rooms are deducted. Guest room-size distribution is based on occupied reservations by total party size (1, 2, or 3+); it does not split adults from children. Overnight guests, completed check-in/check-out counts, and recorded cancellations/no-shows are captured at close. Reservation creations count unique direct/front-desk and iRatePilot website booking records; externally imported OTA bookings are not included unless their connector writes those events. Walk-in bookings are tagged by the PMS walk-in flow and counted only from the property-local tracking start date; older dates are Not recorded. Cancellation and no-show counts use separate immutable request timestamps in the property time zone. Older closes may say Not recorded. Check-in/check-out guest totals use each stay’s recorded party size. PMS-recorded payments, refunds, and payment-record reductions are folio entries grouped by property-local entry timestamp; they do not prove processor capture, bank settlement, or collected cash. Cash/card method breakdowns, adult/child breakdowns, and early activity are not yet captured. Unclosed dates remain unavailable for close-based totals; payment activity can show for open dates.'],['Close and inventory coverage',...columns.map(coverage)],[],['Section','Measure',...columns.map(key=>`${key} (${dateByKey[key].start} to ${dateByKey[key].end} exclusive)` )]];const rows=statisticsSections.flatMap(([section,label])=>[['',label,...columns.map(()=> '')],...frontOfficeStatisticsMetrics.filter(metric=>metric.section===section).map(metric=>[section,metric.label,...columns.map(key=>{const report=reports[key],raw=value(metric,key);return raw===null&&report?frontOfficeStatisticsAvailability(metric.key,report,dateByKey[key]):raw===null?'Unavailable':display(raw,metric.format)})])]);downloadReport(membership.property_name+'-front-office-statistics-'+reportDate,[...metadata,...rows])}
 const titlePeriods=columns.map(key=>dateByKey[key]);
 return <section className="card pilot-reports pilot-front-office-statistics" aria-label="Front-office statistics">
  <div className="pilot-report-controls"><div className="section-top"><div><h2>Front-office statistics</h2><p>One-page room and revenue comparison, based on verified nightly close records.</p></div><div className="pilot-actions"><button className="secondary" disabled={!fresh} onClick={exportCsv}><Download size={16}/>Export CSV</button><button className="secondary" disabled={!fresh} onClick={()=>window.print()}><Printer size={16}/>Print / save PDF</button></div></div>
   <form className="pilot-report-filters pilot-front-office-filters" onSubmit={e=>{e.preventDefault();void load(reportDate)}}><label className="field">Service date<input type="date" required value={reportDate} disabled={busy} onChange={e=>setReportDate(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?<><RefreshCw size={16}/>Loading…</>:<>Load statistics</>}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}
  </div>
  {!fresh?<output className="pilot-empty">{busy?'Loading the six comparison periods…':'Load a service date to view or export the report.'}</output>:<div className="pilot-report-print pilot-front-office-print">
   <header className="pilot-front-office-heading"><div><span className="pilot-eyebrow">{membership.property_name}</span><h2>Statistics Report for {reportDate}</h2><p>Service date · {membership.time_zone} · USD</p></div><small>Generated {new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date())}</small></header>
   <p className="pilot-front-office-basis">This report uses completed service-day records. Out-of-inventory rooms are physical units above configured capacity; available rooms exclude those units before maintenance/out-of-order rooms are deducted. Guest room-size distribution is based on occupied reservations by total party size (1, 2, or 3+); it does not split adults from children. Overnight guest totals, check-ins/check-outs, and recorded cancellations/no-shows are captured for each property's local business date. Reservation creations count unique direct/front-desk and iRatePilot website booking records; externally imported OTA bookings are not included unless their connector writes those events. Walk-in bookings are tagged by the PMS walk-in flow and reported from the property's local tracking start date; older dates show Not recorded. Cancellation and no-show counts use separate immutable request records, so no-shows are not included in cancellations. Older closes may show Not recorded. Check-in/check-out guest totals use each stay’s recorded party size. PMS-recorded payments, refunds, and payment-record reductions use their property-local folio entry timestamp; they do not prove processor capture, bank settlement, or collected cash. Cash/card method totals, adult/child breakdowns, and early activity have not yet been captured. Payment activity can appear before the service day is closed; close-based totals remain unavailable for unclosed dates.</p>
   <div className="pilot-table-wrap"><table className="pilot-table pilot-front-office-table"><caption className="sr-only">Front-office statistics for {membership.property_name} on {reportDate}</caption><thead><tr><th rowSpan={2} scope="col">Measure</th><th colSpan={3} scope="colgroup">This Year</th><th colSpan={3} scope="colgroup">Last Year</th></tr><tr>{titlePeriods.map((period,index)=><th scope="col" key={columns[index]}>{periodLabel(period)}<small>{period.start}</small><small className="pilot-report-coverage">{coverage(columns[index])}</small></th>)}</tr></thead><tbody>{statisticsSections.map(([section,label])=><FragmentSection key={section} section={section} label={label} columns={columns} value={value} reports={reports} dateByKey={dateByKey}/>)}</tbody></table></div>
   <footer className="pilot-front-office-footnote">ADR and RevPAR use original overnight accommodation only. Total recorded revenue includes accommodation, posted accommodation corrections, taxes, and property fees; it is not payment settlement or profit. Room counts are reported as room-nights for multi-day periods.</footer>
  </div>}
 </section>;
}

function frontOfficeStatisticsStatisticsValue(key:string,report:PerformanceReport,period:StatisticsPeriod){return frontOfficeStatisticsValue(key,report,period)}
function FragmentSection({section,label,columns,value,reports,dateByKey}:{section:string;label:string;columns:StatisticsPeriod['key'][];value:(metric:StatisticsMetric,key:StatisticsPeriod['key'])=>string|null;reports:Partial<Record<StatisticsPeriod['key'],PerformanceReport>>;dateByKey:Record<StatisticsPeriod['key'],StatisticsPeriod>}){
 return <>{<tr className="pilot-front-office-section"><th colSpan={7} scope="colgroup">{label}</th></tr>}{frontOfficeStatisticsMetrics.filter(metric=>metric.section===section).map(metric=><tr key={metric.key}><th scope="row">{metric.label}</th>{columns.map(key=>{const report=reports[key],cell=value(metric,key),missing=report&&cell===null?frontOfficeStatisticsAvailability(metric.key,report,dateByKey[key]):null;return <td key={key} className={cell===null?'is-unavailable':''}>{cell===null?(missing??'Unavailable'):display(cell,metric.format)}</td>})}</tr>)}</>;
}
